 1	/**
 2	 * Shared test utilities for all unit test suites in `src/tests/`.
 3	 *
 4	 * Exports:
 5	 *  - `makeTestConfig`        — builds a minimal `AppConfig` rooted at a temp directory.
 6	 *  - `createTempDirTracker`  — creates self-cleaning temp directories for test isolation.
 7	 *  - `setupFakeGit`          — installs a fake `git` binary that records invocations.
 8	 */
 9	
10	import * as fs from 'node:fs';
11	import * as os from 'os';
12	import * as path from 'node:path';
13	
14	import { type AppConfig } from '../config/config.types.js';
15	
16	/**
17	 * Creates a minimal `AppConfig` suitable for use in unit tests.
18	 *
19	 * `storageFolder` and `projectsFolder` are derived from the supplied `base`
20	 * directory so that each test can work inside its own isolated temp tree.
21	 * All other fields are set to sensible defaults that match production
22	 * defaults.  Pass `overrides` to adjust individual fields without having to
23	 * repeat the full object literal.
24	 *
25	 * @param base      - Root temp-directory for this test (e.g. the value
26	 *                    returned by your `makeTempDir()` call).
27	 * @param overrides - Optional partial config to merge on top of the defaults.
28	 * @returns A complete `AppConfig` object.
29	 */
30	export function makeTestConfig(base: string, overrides?: Partial<AppConfig>): AppConfig {
31	    return {
32	        storageFolder: path.join(base, 'storage'),
33	        projectsFolder: path.join(base, 'projects'),
34	        cloneDepth: 50,
35	        serverPort: 4200,
36	        gitPollingIntervalSeconds: 30,
37	        notesCardHeight: 220,
38	        notesColumns: 2,
39	        ...overrides,
40	    };
41	}
42	
43	/**
44	 * Creates a temp-directory tracker that auto-cleans all created directories
45	 * on process exit. Call the returned function to create a new temp directory.
46	 *
47	 * @param prefix - The temp directory name prefix (e.g. `'paralizer-config-test-'`).
48	 * @returns A `makeTempDir()` function that creates and tracks temp directories.
49	 */
50	export function createTempDirTracker(prefix: string): () => string {
51	    const cleanupPaths: string[] = [];
52	    process.on('exit', () => {
53	        for (const p of cleanupPaths) {
54	            fs.rmSync(p, { recursive: true, force: true });
55	        }
56	    });
57	    return (): string => {
58	        const dir = fs.mkdtempSync(path.join(os.tmpdir(), prefix));
59	        cleanupPaths.push(dir);
60	        return dir;
61	    };
62	}
63	
64	/**
65	 * Creates a fake `git` executable in `dir` that records all invocation
66	 * arguments to `dir/captured-args.txt` and exits with code 128 (simulating a
67	 * failed clone).  The real git binary is never called.
68	 *
69	 * @returns Path of the file where captured arguments are written.
70	 */
71	export function setupFakeGit(dir: string): string {
72	    const capturedArgsFile = path.join(dir, 'captured-args.txt');
73	    const fakeGitPath = path.join(dir, 'git');
74	    fs.writeFileSync(
75	        fakeGitPath,
76	        `#!/bin/sh\necho "$@" >> ${capturedArgsFile}\nexit 128\n`,
77	        { mode: 0o755 },
78	    );
79	    return capturedArgsFile;
80	}

